package main

import (
	"fmt"
	"unicode/utf8"
)

func main() {
	s := "héllo" // 'é' is U+00E9, encoded as 2 UTF-8 bytes (0xc3 0xa9)

	fmt.Println("len(s) bytes:", len(s))                       // byte count
	fmt.Println("rune count:  ", utf8.RuneCountInString(s))    // character count
	fmt.Println("[]rune len:  ", len([]rune(s)))               // same character count

	// Indexing returns a BYTE (uint8), not a character.
	fmt.Printf("s[0] = %d (type byte)\n", s[0]) // 'h' = 104
	fmt.Printf("s[1] = %d (first byte of é)\n", s[1]) // 195, NOT 'é'

	// You CANNOT assign to s[i] — strings are immutable.
	// s[0] = 'H' // <- this would be a compile error: cannot assign to s[0]
}

package main

import "fmt"

func main() {
	s := "héllo" // bytes: h=0, é=1..2, l=3, l=4, o=5

	// range decodes one rune per step; i is the BYTE index where the rune starts.
	for i, r := range s {
		fmt.Printf("byteIndex=%d rune=%q codepoint=U+%04X width=%d\n",
			i, r, r, len(string(r)))
	}

	// Contrast: indexing by byte walks the raw storage, not characters.
	fmt.Print("raw bytes: ")
	for i := 0; i < len(s); i++ {
		fmt.Printf("%d ", s[i])
	}
	fmt.Println()
}

package main

import "fmt"

func main() {
	s := "世界" // two CJK runes, each 3 UTF-8 bytes => 6 bytes total

	b := []byte(s) // copy raw bytes (mutable); len 6
	r := []rune(s) // decode code points (mutable); len 2
	fmt.Println("[]byte len:", len(b), "[]rune len:", len(r))

	// Mutating the []rune copy does NOT affect s (immutability preserved via copy).
	r[0] = '你'
	fmt.Println("mutated rune slice ->", string(r)) // re-encode to UTF-8 string
	fmt.Println("original s unchanged ->", s)

	// string(rune) encodes a code point; do NOT use string(int) for numbers.
	fmt.Println(string(rune(65))) // "A" — code point 65
	// For the text "65" use strconv.Itoa(65); string(65) is a vet-flagged rune conversion.
}

package main

import (
	"fmt"
	"strings"
)

func main() {
	words := []string{"Go", "strings", "are", "bytes"}

	// Anti-pattern: each += allocates a new string and copies everything (O(n^2)).
	slow := ""
	for _, w := range words {
		slow += w + " "
	}

	// Idiomatic: strings.Builder writes into a growing buffer, one final string.
	var b strings.Builder
	b.Grow(32) // optional: preallocate to avoid regrowth
	for i, w := range words {
		if i > 0 {
			b.WriteByte(' ') // append a single byte
		}
		b.WriteString(w) // append a string
	}
	b.WriteRune('!') // append a single rune (UTF-8 encoded)

	fmt.Printf("slow:    %q\n", strings.TrimSpace(slow))
	fmt.Printf("builder: %q\n", b.String())
}
